def pasar_a_lista(apps, schema_editor):
    """El incentivo en dinero y el premio que ya existían pasan a la nueva lista de incentivos."""
    Meta = apps.get_model("metas", "MetaMensual")
    Incentivo = apps.get_model("metas", "IncentivoMeta")
    for m in Meta.objects.all():
        if m.incentivo_base:
            Incentivo.objects.create(meta=m, tipo="dinero", monto=m.incentivo_base)
        if m.premio:
            Incentivo.objects.create(meta=m, tipo="regalo", descripcion=m.premio)


